from names import full_name


def test_full_name():
    assert full_name("Ada", "Lovelace") == "Ada Lovelace"

files.test_lists.py:
from lists import head


def test_head_nonempty():
    assert head([1, 2, 3]) == 1


def test_head_empty():
    assert head([]) is None

